CREATE TABLE rm_intercompany_mapping_events (
 id INTEGER PRIMARY KEY CHECK(id > 0),
 mapping_id TEXT NOT NULL CHECK(length(mapping_id) BETWEEN 1 AND 64 AND substr(mapping_id,1,1) GLOB '[a-z]' AND mapping_id NOT GLOB '*[^a-z0-9-]*'),
 event_type TEXT NOT NULL CHECK(event_type IN ('proposed','approved','revoked')),
 mapping_hash TEXT NOT NULL CHECK(length(mapping_hash)=64 AND mapping_hash NOT GLOB '*[^0-9a-f]*'),
 canonical_mapping TEXT NOT NULL CHECK(length(canonical_mapping) BETWEEN 2 AND 65536),
 previous_hash TEXT CHECK(previous_hash IS NULL OR (length(previous_hash)=64 AND previous_hash NOT GLOB '*[^0-9a-f]*')),
 event_hash TEXT NOT NULL UNIQUE CHECK(length(event_hash)=64 AND event_hash NOT GLOB '*[^0-9a-f]*'),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 created_at TEXT NOT NULL CHECK(length(created_at) BETWEEN 19 AND 30)
);
CREATE INDEX rm_intercompany_mapping_events_current_idx ON rm_intercompany_mapping_events(mapping_id,id DESC);
CREATE TRIGGER rm_intercompany_mapping_events_no_update BEFORE UPDATE ON rm_intercompany_mapping_events BEGIN SELECT RAISE(ABORT, 'intercompany mapping events are append-only'); END;
CREATE TRIGGER rm_intercompany_mapping_events_no_delete BEFORE DELETE ON rm_intercompany_mapping_events BEGIN SELECT RAISE(ABORT, 'intercompany mapping events are append-only'); END;
